// Node skeleton: prompt → call → validate → update-or-quarantine
async function triageNode(callModel, state) {
  const raw = await callModel(TRIAGE_PROMPT + state.ticket); // bounded retries/timeout inside callModel
  const parsed = extractJSON(raw);                            // Ch.3 Prompt-101 parser
  if (!parsed.ok) return { _quarantined: { node: "triage", raw } };
  const { category, confidence } = parsed.value;
  if (!["billing", "shipping", "returns"].includes(category))
    return { _quarantined: { node: "triage", reason: "bad enum", raw } };
  return { category, triageConfidence: confidence };           // clean partial update
}
// Downstream reads category only when no _quarantined flag exists.

// Bounded retry with quoted-error repair (plain JS pattern)
async function callWithRepair(callModel, prompt, validate, maxTries = 2) {
  let lastError = null;
  for (let i = 0; i < maxTries; i++) {
    const raw = await callModel(prompt + (lastError ? `\nPrevious output was invalid: ${lastError}. Fix it.` : ""));
    const v = validate(raw);
    if (v.ok) return v;
    lastError = v.error;
  }
  return { ok: false, error: lastError, quarantined: true };
}
// Repair quotes the violation back — models fix stated errors far better than vibes.

