function validateTriage(parsed) {
  if (!parsed || typeof parsed !== 'object') return { ok: false, error: 'not-an-object' };
  if (!['billing', 'shipping', 'returns'].includes(parsed.category)) return { ok: false, error: 'bad-enum:' + parsed.category };
  if (typeof parsed.confidence !== 'number' || parsed.confidence < 0 || parsed.confidence > 1) return { ok: false, error: 'bad-confidence' };
  return { ok: true };
}
const cases = [
  { category: 'shipping', confidence: 0.9 },
  { category: 'Exchange', confidence: 0.9 },
  { category: 'billing', confidence: 'high' },
  'just a string',
];
for (const c of cases) console.log(JSON.stringify(validateTriage(c)));

